/** Cheerful lines for the level-complete card. */
val cheers = listOf(
    "Nicely sorted!",
    "Sand-tastic!",
    "Purr-fect pour!",
    "Tidy as can be!",
    "Pawsome work!",
    "Neat and cozy!",
    "Every grain home!",
)

/**
 * The cheer shown for [levelNumber]: always the same for a level, and never the same for two levels in a row
 * (the stride 3 is coprime to the 7 cheers, so it walks through all of them).
 */
fun cheerFor(levelNumber: Int): String = cheers[((levelNumber - 1) * 3).mod(cheers.size)]

/**
 * Shown over the board once the level is solved: a soft confetti shower and, after a short beat, a speech-bubble
 * card that pops in with a gentle bounce and leads to the next level. When the level's keepsake has a game (see
 * [playableKeepsake]), the card shows its keepsake star beside the puzzle stars and, once the keepsake has popped
 * in, offers to play with it: [onPlayKeepsake].
 */
@Composable
fun LevelComplete(game: GameController, onPlayKeepsake: () -> Unit = {}) {
    val palette = LocalPalette.current
    val level = game.levelNumber
    val scrim = remember(level) { Animatable(0f) }
    val pop = remember(level) { Animatable(0f) }
    LaunchedEffect(level) { scrim.animateTo(1f, tween(500)) }
    LaunchedEffect(level) {
        delay(350)
        pop.animateTo(1f, spring(dampingRatio = 0.5f, stiffness = Spring.StiffnessLow))
    }
    Box(
        Modifier.fillMaxSize().background(palette.scrim.copy(alpha = palette.scrim.alpha * 0.5f * scrim.value)),
        contentAlignment = Alignment.Center,
    ) {
        // Behind the card, so it never covers the text.
        Confetti(seed = level, modifier = Modifier.fillMaxSize())
        // Centered when it fits; in a short window the card scrolls, so Next level always stays reachable.
        BoxWithConstraints(Modifier.fillMaxSize()) {
            Box(
                Modifier.fillMaxWidth().verticalScroll(rememberScrollState()).heightIn(min = maxHeight),
                contentAlignment = Alignment.Center,
            ) {
                Box(
                    Modifier
                        .padding(24.dp)
                        .graphicsLayer {
                            val s = 0.6f + 0.4f * pop.value
                            scaleX = s
                            scaleY = s
                            alpha = pop.value.coerceIn(0f, 1f)
                            transformOrigin = TransformOrigin(0.5f, 1f)
                        },
                ) {
                    WithGameFont { SolvedCard(game, palette, onPlayKeepsake) }
                }
            }
        }
    }
}

@Composable
private fun SolvedCard(game: GameController, palette: Palette, onPlayKeepsake: () -> Unit) {
    val keepsake = game.playableKeepsake(game.levelNumber)
    val bubble = SpeechBubbleShape(corner = 28.dp, tailWidth = 26.dp, tailHeight = 14.dp)
    Box(Modifier.widthIn(max = 320.dp)) {
        Column(
            Modifier
                .padding(top = 14.dp)
                .shadow(10.dp, bubble, ambientColor = Color.Black.copy(alpha = 0.3f), spotColor = Color.Black.copy(alpha = 0.3f))
                .background(palette.accent, bubble)
                .padding(start = 28.dp, end = 28.dp, top = 30.dp, bottom = 22.dp + 14.dp),
            horizontalAlignment = Alignment.CenterHorizontally,
        ) {
            Text(
                cheerFor(game.levelNumber),
                color = palette.onAccent,
                fontSize = 26.sp,
                fontWeight = FontWeight.ExtraBold,
                textAlign = TextAlign.Center,
                lineHeight = 30.sp,
            )
            Spacer(Modifier.height(12.dp))
            Row(verticalAlignment = Alignment.CenterVertically) {
                EarnedStars(game.levelNumber, game.earnedStars, palette.onAccent.copy(alpha = 0.45f))
                if (keepsake != null) {
                    Spacer(Modifier.width(6.dp))
                    KeepsakeBadge(keepsake.arena, keepsake.stage, game.levelNumber in game.keepsakeStars, Modifier.size(38.dp))
                }
            }
            Spacer(Modifier.height(8.dp))
            val par = Stars.par(game.levelNumber)
            Text(
                "${game.moveCount} moves" + if (par != null) "  ·  Par $par" else "",
                color = palette.onAccent,
                fontSize = 15.sp,
                fontWeight = FontWeight.Bold,
            )
            Spacer(Modifier.height(18.dp))
            PillButton("Next level", game::nextLevel, ButtonStyle.go(palette))
            if (keepsake != null) {
                Spacer(Modifier.height(12.dp))
                PlayKeepsakeButton(game.levelNumber, keepsake, onPlayKeepsake)
            }
        }
        // A tilted name tag on the bubble's top edge, like a speaker's name.
        Text(
            "Level ${game.levelNumber} solved",
            color = palette.onAccent,
            fontSize = 14.sp,
            fontWeight = FontWeight.Bold,
            modifier = Modifier
                .align(Alignment.TopStart)
                .offset(x = 4.dp)
                .rotate(-5f)
                .background(lerp(palette.highlight, palette.accent, 0.25f), RoundedCornerShape(50))
                .padding(horizontal = 14.dp, vertical = 6.dp),
        )
        BouncingPaw(
            color = lerp(palette.sand(SandColor.PINK), palette.accent, 0.35f),
            modifier = Modifier.align(Alignment.TopEnd).offset(x = (-6).dp, y = (-10).dp),
        )
    }
}

/**
 * The [earned] stars of three, filling in one after another with a springy pop and a burst of sparkles.
 * The middle star is bigger and raised, like on a podium; stars not earned stay as empty slots in [emptyColor].
 */
@Composable
private fun EarnedStars(level: Int, earned: Int, emptyColor: Color) {
    val pops = remember(level) { List(Stars.MAX) { Animatable(0f) } }
    val bursts = remember(level) { List(Stars.MAX) { Animatable(0f) } }
    LaunchedEffect(level) {
        // Wait for the card to land, then fill the stars in turn.
        delay(650)
        for (i in 0 until earned) {
            launch { pops[i].animateTo(1f, spring(dampingRatio = 0.38f, stiffness = Spring.StiffnessMediumLow)) }
            launch { bursts[i].animateTo(1f, tween(600, easing = FastOutSlowInEasing)) }
            delay(330)
        }
    }
    Row(
        verticalAlignment = Alignment.Bottom,
        modifier = Modifier.clearAndSetSemantics { contentDescription = "$earned of ${Stars.MAX} stars" },
    ) {
        repeat(Stars.MAX) { i ->
            val middle = i == 1
            Box(
                Modifier
                    .size(if (middle) 62.dp else 48.dp)
                    .offset(y = if (middle) (-8).dp else 0.dp)
                    .rotate(if (middle) 0f else if (i == 0) -12f else 12f),
            ) {
                Canvas(Modifier.matchParentSize()) {
                    drawStar(earned = false, emptyColor = emptyColor)
                    val t = bursts[i].value
                    if (t > 0f && t < 1f) sparkles(t)
                }
                Canvas(
                    Modifier.matchParentSize().graphicsLayer {
                        val v = pops[i].value
                        scaleX = v
                        scaleY = v
                        alpha = v.coerceIn(0f, 1f)
                    },
                ) { drawStar(earned = true, emptyColor = emptyColor) }
            }
        }
    }
}

/** Eight little sparkles flying out from the center and fading, [t] from 0 to 1. */
private fun DrawScope.sparkles(t: Float) {
    val reach = size.minDimension * (0.45f + 0.5f * t)
    for (k in 0 until 8) {
        val a = k * PI / 4 + PI / 8
        val c = center + Offset((cos(a) * reach).toFloat(), (sin(a) * reach).toFloat())
        val color = if (k % 2 == 0) Color(0xFFFFE27A) else Color.White
        drawCircle(color.copy(alpha = 1f - t), size.minDimension * 0.06f * (1f - t * 0.5f), c)
    }
}

/** A little paw print that hops gently in place. */
@Composable
private fun BouncingPaw(color: Color, modifier: Modifier = Modifier) {
    val hop by rememberInfiniteTransition().animateFloat(
        initialValue = 0f,
        targetValue = 1f,
        animationSpec = infiniteRepeatable(tween(700, easing = FastOutSlowInEasing), RepeatMode.Reverse),
    )
    Canvas(
        modifier
            .size(40.dp)
            .graphicsLayer {
                translationY = -5.dp.toPx() * hop
                rotationZ = 14f - 6f * hop
            },
    ) {
        val u = size.minDimension / 10f
        // Main pad: a soft rounded triangle made of three overlapping circles.
        drawCircle(color, radius = 2.2f * u, center = Offset(5f * u, 6.6f * u))
        drawCircle(color, radius = 1.9f * u, center = Offset(3.9f * u, 7.4f * u))
        drawCircle(color, radius = 1.9f * u, center = Offset(6.1f * u, 7.4f * u))
        // Four toe beans.
        drawOval(color, Offset(0.9f * u, 3.4f * u), Size(1.9f * u, 2.4f * u))
        drawOval(color, Offset(2.9f * u, 1.4f * u), Size(1.9f * u, 2.5f * u))
        drawOval(color, Offset(5.2f * u, 1.4f * u), Size(1.9f * u, 2.5f * u))
        drawOval(color, Offset(7.2f * u, 3.4f * u), Size(1.9f * u, 2.4f * u))
    }
}

/** A rounded speech bubble with a small tail at the bottom center, inside the bottom [tailHeight]. */
private class SpeechBubbleShape(
    private val corner: Dp,
    private val tailWidth: Dp,
    private val tailHeight: Dp,
) : Shape {
    override fun createOutline(size: Size, layoutDirection: LayoutDirection, density: Density): Outline {
        val r = with(density) { corner.toPx() }
        val tw = with(density) { tailWidth.toPx() }
        val th = with(density) { tailHeight.toPx() }
        val body = size.height - th
        val cx = size.width / 2
        val path = Path().apply {
            addRoundRect(RoundRect(0f, 0f, size.width, body, CornerRadius(r)))
            // The tail leans a little to one side and ends in a soft point.
            moveTo(cx - tw / 2, body - 1f)
            quadraticBezierTo(cx - tw * 0.1f, body + th * 0.4f, cx - tw * 0.2f, size.height)
            quadraticBezierTo(cx + tw * 0.25f, body + th * 0.45f, cx + tw / 2, body - 1f)
            close()
        }
        return Outline.Generic(path)
    }
}
