package io.colorsand.ui.fx

import androidx.compose.runtime.Composable
import androidx.compose.runtime.LaunchedEffect
import androidx.compose.runtime.Stable
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.remember
import androidx.compose.runtime.setValue
import androidx.compose.runtime.snapshotFlow
import io.colorsand.ui.GameController
import io.colorsand.ui.PourAnimation
import io.colorsand.ui.PourEvent
import io.colorsand.ui.ProgressStore
import io.colorsand.ui.drained
import io.colorsand.ui.landed
import kotlinx.coroutines.flow.drop
import kotlinx.coroutines.flow.filter
import kotlinx.coroutines.flow.takeWhile

/** The sounds and haptics of the game, and the player's settings for them (kept in a [ProgressStore]). */
@Stable
class Feedback internal constructor(
    private val store: ProgressStore,
    private val player: SoundPlayer,
    private val haptics: Haptics,
) {
    private var soundState by mutableStateOf(store.sound)
    private var hapticsState by mutableStateOf(store.haptics)

    /** Whether sound effects play. */
    var soundOn: Boolean
        get() = soundState
        set(value) {
            soundState = value
            store.sound = value
        }

    /** Whether haptic ticks play. */
    var hapticsOn: Boolean
        get() = hapticsState
        set(value) {
            hapticsState = value
            store.haptics = value
        }

    /** Whether this device can vibrate; the haptics setting is only shown where it can. */
    val hasHaptics: Boolean get() = haptics.available

    fun play(sound: Sound) {
        if (soundOn) player.play(sound)
    }

    fun stop(sound: Sound) = player.stop(sound)

    fun tick() {
        if (hapticsOn) haptics.tick()
    }

    fun confirm() {
        if (hapticsOn) haptics.confirm()
    }
}

/** Where a pour is, for its sounds: the tube being lifted, sand running, or all of it landed. */
internal enum class PourStage { LIFTING, RUNNING, LANDED }

/** The [PourStage] at pour animation progress [p], from the animation's own [drained] and [landed]. */
internal fun pourStage(p: Float): PourStage = when {
    landed(p) >= 1f -> PourStage.LANDED
    drained(p) > 0f -> PourStage.RUNNING
    else -> PourStage.LIFTING
}

/**
 * Plays the game's sounds and haptics at the right moments, and returns the [Feedback] for the settings:
 * picking a tube up, a tap that can't pour (see [GameController.lastRejected]), the sand running and landing in
 * step with [pours], a chime for a finished tube, an arpeggio as the level-complete card comes up, and a click
 * for the game's buttons.
 */
@Composable
fun rememberGameFeedback(game: GameController, pours: PourAnimation, store: ProgressStore): Feedback {
    val player = rememberSoundPlayer()
    val haptics = rememberHaptics()
    val feedback = remember(store, player, haptics) { Feedback(store, player, haptics) }

    LaunchedEffect(game, feedback) {
        var rejected = game.lastRejected?.id
        snapshotFlow { game.selected to game.lastRejected?.id }.collect { (selected, id) ->
            if (id != rejected) {
                rejected = id
                feedback.play(Sounds.invalid)
            } else if (selected != null) {
                feedback.play(Sounds.pick)
                feedback.tick()
            }
        }
    }
    LaunchedEffect(game.lastPour, feedback) { game.lastPour?.let { playPour(it, game, pours, feedback) } }
    LaunchedEffect(game, feedback) {
        // As the level-complete card comes up (see App): after the last grains have landed.
        snapshotFlow { game.isSolved && !pours.isRunning }.drop(1).filter { it }.collect {
            feedback.play(Sounds.solved)
            feedback.confirm()
        }
    }
    LaunchedEffect(game, feedback) {
        snapshotFlow { game.actions }.drop(1).collect { feedback.play(Sounds.click) }
    }
    return feedback
}

/**
 * Follows the animation of [event]: the hiss starts with the stream, and the landing (and the chime, if the tube
 * is finished) comes when the last grain lands. A pour cut short by a tap lands at once; one undone mid-way doesn't.
 */
private suspend fun playPour(event: PourEvent, game: GameController, pours: PourAnimation, feedback: Feedback) {
    var running = false
    var settled = false
    try {
        snapshotFlow { if (pours.pour?.id == event.id) pourStage(pours.progress) else null }
            .takeWhile { it != null && it != PourStage.LANDED }
            .collect { stage ->
                if (stage == PourStage.RUNNING && !running) {
                    running = true
                    feedback.play(Sounds.pour)
                    feedback.tick()
                }
            }
        settled = pourStage(pours.progress) == PourStage.LANDED && pours.pour?.id == event.id
    } finally {
        if (!settled) feedback.stop(Sounds.pour)
        // Undo, restart and a new level clear the last pour: then nothing lands.
        if (game.lastPour != null) {
            feedback.play(Sounds.land)
            if (event.finishesTube) {
                feedback.play(Sounds.chime(event.streak))
                feedback.confirm()
            }
        }
    }
}
