package io.colorsand.ui.hud

import androidx.compose.ui.Modifier
import androidx.compose.ui.draw.drawWithCache
import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.geometry.Size
import androidx.compose.ui.graphics.Brush
import androidx.compose.ui.graphics.ClipOp
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.Path
import androidx.compose.ui.graphics.Shadow
import androidx.compose.ui.graphics.Shape
import androidx.compose.ui.graphics.addOutline
import androidx.compose.ui.graphics.drawOutline
import androidx.compose.ui.graphics.drawscope.Stroke
import androidx.compose.ui.graphics.drawscope.clipPath
import androidx.compose.ui.graphics.drawscope.translate
import androidx.compose.ui.graphics.lerp
import androidx.compose.ui.text.TextStyle
import androidx.compose.ui.unit.Dp
import androidx.compose.ui.unit.dp
import io.colorsand.ui.Palette

/**
 * A frosted glass panel for HUD pieces that sit on the scenery: the palette's surface, mostly opaque so text reads
 * over any background, a faint sheen at the top, a thin light rim and a soft drop shadow of [elevation].
 *
 * The shadow is drawn only outside the panel (a platform shadow would show through the see-through surface).
 */
fun Modifier.frosted(palette: Palette, shape: Shape, elevation: Dp = 8.dp): Modifier = drawWithCache {
    val base = palette.surface
    val top = lerp(base, Color.White, if (palette.isLight) 0.5f else 0.1f)
    val rimColor = if (palette.isLight) Color.White else Color.White.copy(alpha = 0.28f)
    val shade = if (palette.isLight) Color(0xFF6A4128) else Color.Black
    val outline = shape.createOutline(size, layoutDirection, this)
    val inside = Path().apply { addOutline(outline) }
    val fill = Brush.verticalGradient(listOf(top.copy(alpha = 0.9f), base.copy(alpha = 0.84f)))
    val rim = Brush.verticalGradient(listOf(rimColor, rimColor.copy(alpha = rimColor.alpha * 0.35f)))
    val rimStroke = Stroke(1.dp.toPx())
    // The shadow: a few growing, fading copies of the outline, a little below the panel.
    val reach = elevation.toPx()
    val steps = 8
    val halo = List(steps) { i ->
        val grow = reach * (i + 1) / steps
        shape.createOutline(Size(size.width + 2 * grow, size.height + 2 * grow), layoutDirection, this) to grow
    }
    val haloColor = shade.copy(alpha = (if (palette.isLight) 0.14f else 0.24f) / steps)
    onDrawBehind {
        clipPath(inside, ClipOp.Difference) {
            for ((o, grow) in halo) {
                translate(left = -grow, top = -grow + reach * 0.6f) { drawOutline(o, haloColor) }
            }
        }
        drawOutline(outline, fill)
        drawOutline(outline, rim, style = rimStroke)
    }
}

/** A soft drop shadow under bold titles, so they stand out on panels and scenery alike. */
fun TextStyle.withTitleShadow(palette: Palette): TextStyle = copy(
    shadow = Shadow(
        color = if (palette.isLight) Color.White.copy(alpha = 0.8f) else Color.Black.copy(alpha = 0.45f),
        offset = Offset(0f, 2f),
        blurRadius = 3f,
    ),
)
