package io.colorsand.ui.arena

import androidx.compose.ui.Modifier
import androidx.compose.ui.draw.drawWithCache
import androidx.compose.ui.geometry.CornerRadius
import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.geometry.RoundRect
import androidx.compose.ui.geometry.Size
import androidx.compose.ui.graphics.Brush
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.Path
import androidx.compose.ui.graphics.StrokeCap
import androidx.compose.ui.graphics.drawscope.DrawScope
import androidx.compose.ui.graphics.drawscope.Stroke
import androidx.compose.ui.graphics.drawscope.clipRect
import androidx.compose.ui.graphics.drawscope.withTransform
import androidx.compose.ui.unit.Dp
import io.colorsand.core.Arena
import kotlin.random.Random

/**
 * Draws the stand a row of [tubes] tubes rests on, behind the row: a wooden sandbox edge at the Playground, a
 * driftwood plank at the Beach, a barnacled rock ledge on the Sea Floor, a carved sandstone ledge in the Desert,
 * a hazard-striped steel I-beam at the Building Site, a riveted metal platform on Mars, with a soft shadow under
 * each tube.
 * The row is the tubes, [tubeWidth] wide and [gap] apart, standing on the bottom edge of this element.
 */
fun Modifier.tubeStand(arena: Arena, tubes: Int, tubeWidth: Dp, gap: Dp): Modifier = drawWithCache {
    val w = tubeWidth.toPx()
    val step = w + gap.toPx()
    val look = standLook(arena)
    val left = -w * 0.38f
    val right = size.width + w * 0.38f
    val surface = size.height - w * 0.2f // the top of the stand, seen from a little above
    val front = size.height + w * 0.13f // where its front face starts
    val under = front + w * 0.34f
    val topFace = standTop(arena, left, right, surface, front, w)
    val face = standFace(arena, left, right, front, under, w)
    val faceBrush = Brush.verticalGradient(listOf(look.face, look.faceDark), startY = front, endY = under)
    val topBrush = Brush.verticalGradient(listOf(look.topLight, look.top), startY = surface, endY = front)
    val shadow = Brush.radialGradient(0f to Color.Black.copy(alpha = 0.42f), 0.55f to Color.Black.copy(alpha = 0.2f), 1f to Color.Transparent, center = Offset.Zero, radius = w * 0.8f)
    val marks = standMarks(arena, left, right, front, under, w)
    onDrawBehind {
        // The stand's own shadow on whatever is behind it.
        drawRoundRect(Color.Black.copy(alpha = 0.16f), Offset(left + w * 0.1f, front + w * 0.12f), Size(right - left, under - front + w * 0.06f), CornerRadius(w * 0.2f))
        drawPath(face, faceBrush)
        drawPath(topFace, topBrush)
        marks(this, look)
        // The lit front edge.
        drawLine(look.edge, Offset(left + w * 0.12f, front + w * 0.015f), Offset(right - w * 0.12f, front + w * 0.015f), strokeWidth = w * 0.035f, cap = StrokeCap.Round)
        for (i in 0 until tubes) {
            val cx = i * step + w / 2
            val c = Offset(cx, size.height - w * 0.03f)
            drawContactShadow(c, w, shadow)
        }
    }
}

/** A soft oval shadow on the stand, centered on [c]. */
private fun DrawScope.drawContactShadow(c: Offset, w: Float, brush: Brush) {
    withTransform({
        translate(c.x, c.y)
        scale(1f, 0.26f, Offset.Zero)
    }) { drawCircle(brush, w * 0.8f, Offset.Zero) }
}

private class StandLook(val top: Color, val topLight: Color, val face: Color, val faceDark: Color, val edge: Color, val mark: Color)

private fun standLook(arena: Arena) = when (arena) {
    Arena.PLAYGROUND -> StandLook(Color(0xFFC98D52), Color(0xFFE2AC6E), Color(0xFFAE6D36), Color(0xFF8A5227), Color(0xFFF0C48C), Color(0xFF6E3F1C))
    Arena.BUILDING_SITE -> StandLook(Color(0xFF97A1AC), Color(0xFFC8D0D8), Color(0xFF8D97A3), Color(0xFF5D6671), Color(0xFFE6EBF0), Color(0xFF2F3134))
    Arena.BEACH -> StandLook(Color(0xFFCDBFA6), Color(0xFFE8DDC8), Color(0xFFB2A188), Color(0xFF8F7F69), Color(0xFFF4ECDD), Color(0xFF7A6B57))
    Arena.SEA_FLOOR -> StandLook(Color(0xFF7F97A2), Color(0xFFA9C0C6), Color(0xFF65808E), Color(0xFF475F6E), Color(0xFFCFE4E6), Color(0xFF34495A))
    Arena.DESERT -> StandLook(Color(0xFFE9A866), Color(0xFFF7C88E), Color(0xFFD28546), Color(0xFFAE6332), Color(0xFFFFD9A4), Color(0xFF8F4C22))
    Arena.MARS -> StandLook(Color(0xFF9EA6B0), Color(0xFFCDD3DA), Color(0xFF7C8592), Color(0xFF555D69), Color(0xFFEEF2F6), Color(0xFF353B45))
}

/** The top of the stand, between its back edge at [surface] and its front edge at [front]. */
private fun standTop(arena: Arena, left: Float, right: Float, surface: Float, front: Float, w: Float) = Path().apply {
    val r = w * 0.12f
    when (arena) {
        // Driftwood: worn, a little wavy along the back.
        Arena.BEACH -> {
            moveTo(left + r, surface + w * 0.03f)
            val n = 6
            for (k in 1..n) {
                val x = left + r + (right - left - 2 * r) * k / n
                quadraticBezierTo(x - (right - left) / n / 2, surface - w * 0.02f * (k % 2), x, surface + w * 0.02f)
            }
            quadraticBezierTo(right, surface + w * 0.04f, right - r * 0.3f, front)
            lineTo(left + r * 0.3f, front)
            quadraticBezierTo(left, surface + w * 0.06f, left + r, surface + w * 0.03f)
        }
        // Rock: a lumpy back edge.
        Arena.SEA_FLOOR -> {
            moveTo(left + r, surface + w * 0.02f)
            val n = 9
            for (k in 1..n) {
                val x = left + r + (right - left - 2 * r) * k / n
                quadraticBezierTo(x - (right - left) / n / 2, surface - w * 0.035f * ((k * 5) % 3) / 2f, x, surface + w * 0.015f)
            }
            quadraticBezierTo(right + r * 0.2f, surface + w * 0.05f, right - r * 0.2f, front)
            lineTo(left + r * 0.2f, front)
            quadraticBezierTo(left - r * 0.2f, surface + w * 0.05f, left + r, surface + w * 0.02f)
        }
        else -> {
            moveTo(left + r, surface)
            lineTo(right - r, surface)
            quadraticBezierTo(right, surface, right, front)
            lineTo(left, front)
            quadraticBezierTo(left, surface, left + r, surface)
        }
    }
    close()
}

/** The front face of the stand, from [front] down to [under]. */
private fun standFace(arena: Arena, left: Float, right: Float, front: Float, under: Float, w: Float) = Path().apply {
    val r = w * 0.14f
    when (arena) {
        // Driftwood: rounded, uneven ends.
        Arena.BEACH -> {
            moveTo(left, front)
            lineTo(right, front)
            cubicTo(right + r, front + w * 0.05f, right + r * 0.4f, under, right - r * 0.8f, under - w * 0.02f)
            lineTo(left + r, under)
            cubicTo(left - r * 0.6f, under - w * 0.02f, left - r * 0.8f, front + w * 0.06f, left, front)
        }
        // Rock: a lumpy underside and rounded, uneven ends.
        Arena.SEA_FLOOR -> {
            moveTo(left, front)
            lineTo(right, front)
            cubicTo(right + r * 0.9f, front + w * 0.06f, right + r * 0.5f, under - w * 0.04f, right - r * 0.6f, under - w * 0.03f)
            val n = 7
            for (k in n - 1 downTo 0) {
                val x = left + r * 0.6f + (right - left - r * 1.2f) * k / n
                quadraticBezierTo(x + (right - left) / n / 2, under + w * 0.03f * (1 + (k % 2)), x, under - w * 0.02f)
            }
            cubicTo(left - r * 0.5f, under - w * 0.04f, left - r * 0.9f, front + w * 0.06f, left, front)
        }
        // Metal platform: bevelled lower corners.
        Arena.MARS -> {
            moveTo(left, front)
            lineTo(right, front)
            lineTo(right, under - w * 0.1f)
            lineTo(right - w * 0.1f, under)
            lineTo(left + w * 0.1f, under)
            lineTo(left, under - w * 0.1f)
        }
        // Sandstone: chipped corners.
        Arena.DESERT -> {
            moveTo(left, front)
            lineTo(right, front)
            lineTo(right + w * 0.04f, front + w * 0.12f)
            lineTo(right - w * 0.03f, under)
            lineTo(left + w * 0.05f, under)
            lineTo(left - w * 0.03f, under - w * 0.1f)
        }
        // A steel beam: square cut ends.
        Arena.BUILDING_SITE -> {
            moveTo(left, front)
            lineTo(right, front)
            lineTo(right, under)
            lineTo(left, under)
        }
        // A sandbox board with rounded corners.
        Arena.PLAYGROUND -> addRoundRect(
            RoundRect(left, front - 0.5f, right, under, CornerRadius(0f), CornerRadius(0f), CornerRadius(r), CornerRadius(r)),
        )
    }
    close()
}

/**
 * The texture on the stand's front: wood grain and bolts, driftwood streaks and knots, carved sandstone,
 * a hazard-striped steel beam.
 */
private fun standMarks(arena: Arena, left: Float, right: Float, front: Float, under: Float, w: Float): (DrawScope, StandLook) -> Unit {
    val rnd = Random(arena.ordinal + 5)
    val span = right - left
    val h = under - front
    return when (arena) {
        Arena.PLAYGROUND -> {
            val grain = List(4) { k ->
                val y = front + h * (0.25f + 0.18f * k)
                Path().apply {
                    moveTo(left + w * 0.2f + rnd.nextFloat() * w, y)
                    val x2 = left + span * (0.4f + rnd.nextFloat() * 0.5f)
                    quadraticBezierTo((left + x2) / 2, y + h * (rnd.nextFloat() - 0.5f) * 0.2f, x2, y + h * 0.04f)
                }
            }
            val seams = List(((span - w) / (w * 4.5f)).toInt().coerceAtLeast(0)) { k -> left + w * 4.5f * (k + 1) }
            val bolts = listOf(left + w * 0.3f, right - w * 0.3f) + seams.flatMap { listOf(it - w * 0.22f, it + w * 0.22f) }
            ({ d, look ->
                grain.forEach { d.drawPath(it, look.mark.copy(alpha = 0.3f), style = Stroke(w * 0.025f, cap = StrokeCap.Round)) }
                seams.forEach { d.drawLine(look.mark.copy(alpha = 0.45f), Offset(it, front), Offset(it, under), strokeWidth = w * 0.03f) }
                bolts.forEach {
                    val c = Offset(it, front + h * 0.5f)
                    d.drawCircle(look.mark.copy(alpha = 0.6f), w * 0.05f, c)
                    d.drawCircle(look.edge.copy(alpha = 0.9f), w * 0.022f, c - Offset(w * 0.012f, w * 0.012f))
                }
            })
        }
        Arena.BUILDING_SITE -> {
            // An I-beam: flanges along the top and bottom, a hazard-striped web between them, rivets on the flanges.
            val webTop = front + h * 0.26f
            val webBottom = under - h * 0.26f
            val stripe = w * 0.16f
            val hazard = Path().apply {
                val tall = webBottom - webTop
                var x = left - tall
                while (x < right) {
                    moveTo(x, webBottom); lineTo(x + stripe, webBottom); lineTo(x + stripe + tall, webTop); lineTo(x + tall, webTop); close()
                    x += stripe * 2
                }
            }
            val rivets = List(((span - w * 0.4f) / (w * 0.5f)).toInt() + 1) { k -> left + w * 0.2f + k * w * 0.5f }
            ({ d, look ->
                d.clipRect(left, webTop, right, webBottom) {
                    drawRect(HAZARD, Offset(left, webTop), Size(span, webBottom - webTop))
                    drawPath(hazard, look.mark)
                    drawRect(Color.Black.copy(alpha = 0.25f), Offset(left, webTop), Size(span, (webBottom - webTop) * 0.22f))
                }
                d.drawLine(look.edge.copy(alpha = 0.6f), Offset(left, webBottom), Offset(right, webBottom), strokeWidth = w * 0.015f)
                rivets.forEach { x ->
                    for (y in listOf(front + h * 0.13f, under - h * 0.12f)) {
                        d.drawCircle(look.mark.copy(alpha = 0.45f), w * 0.026f, Offset(x + w * 0.006f, y + w * 0.006f))
                        d.drawCircle(look.top, w * 0.022f, Offset(x, y))
                        d.drawCircle(look.edge, w * 0.009f, Offset(x - w * 0.006f, y - w * 0.006f))
                    }
                }
            })
        }
        Arena.BEACH -> {
            val streaks = List(5) { k ->
                val y = front + h * (0.18f + 0.16f * k)
                val x1 = left + rnd.nextFloat() * span * 0.4f
                Triple(x1, x1 + span * (0.25f + rnd.nextFloat() * 0.4f), y)
            }
            val knot = Offset(left + span * (0.25f + rnd.nextFloat() * 0.5f), front + h * 0.5f)
            ({ d, look ->
                streaks.forEachIndexed { k, (a, b, y) ->
                    val c = if (k % 2 == 0) look.mark.copy(alpha = 0.3f) else look.edge.copy(alpha = 0.35f)
                    d.drawLine(c, Offset(a, y), Offset(b, y), strokeWidth = w * 0.025f, cap = StrokeCap.Round)
                }
                d.drawOval(look.mark.copy(alpha = 0.5f), knot - Offset(w * 0.12f, w * 0.07f), Size(w * 0.24f, w * 0.14f), style = Stroke(w * 0.03f))
                d.drawOval(look.mark.copy(alpha = 0.55f), knot - Offset(w * 0.04f, w * 0.025f), Size(w * 0.08f, w * 0.05f))
            })
        }
        Arena.SEA_FLOOR -> {
            // Layers in the rock, barnacle clusters, and weed hanging over the front edge.
            val strata = List(3) { k ->
                val y = front + h * (0.3f + 0.22f * k)
                Path().apply {
                    moveTo(left + w * 0.15f + rnd.nextFloat() * w * 0.5f, y)
                    val x2 = right - w * 0.15f - rnd.nextFloat() * span * 0.3f
                    quadraticBezierTo((left + x2) / 2, y + h * (rnd.nextFloat() - 0.5f) * 0.25f, x2, y + h * 0.05f)
                }
            }
            val barnacles = List(((span / (w * 1.6f)).toInt() + 2).coerceAtLeast(3)) { k ->
                val x = left + w * 0.3f + (span - w * 0.6f) * (k + rnd.nextFloat() * 0.6f) / ((span / (w * 1.6f)).toInt() + 2.6f)
                List(2 + rnd.nextInt(3)) { Offset(x + w * (rnd.nextFloat() - 0.5f) * 0.3f, front + h * (0.35f + rnd.nextFloat() * 0.45f)) to w * (0.035f + rnd.nextFloat() * 0.03f) }
            }.flatten()
            val weed = List(((span / (w * 2.2f)).toInt() + 1).coerceAtLeast(2)) { k ->
                val x = left + w * 0.5f + (span - w) * (k + rnd.nextFloat() * 0.5f) / ((span / (w * 2.2f)).toInt() + 1.5f)
                val len = h * (0.35f + rnd.nextFloat() * 0.3f)
                Path().apply {
                    moveTo(x - w * 0.07f, front - w * 0.01f)
                    quadraticBezierTo(x - w * 0.05f, front + len * 0.6f, x, front + len)
                    quadraticBezierTo(x + w * 0.04f, front + len * 0.5f, x + w * 0.07f, front - w * 0.01f)
                    close()
                }
            }
            ({ d, look ->
                strata.forEach { d.drawPath(it, look.mark.copy(alpha = 0.28f), style = Stroke(w * 0.022f, cap = StrokeCap.Round)) }
                barnacles.forEach { (c, r) ->
                    d.drawCircle(look.mark.copy(alpha = 0.35f), r * 1.1f, c + Offset(r * 0.15f, r * 0.2f))
                    d.drawCircle(Color(0xFFE6E2D4), r, c)
                    d.drawCircle(Color(0xFFB9B4A4), r * 0.55f, c)
                    d.drawCircle(look.mark.copy(alpha = 0.8f), r * 0.28f, c)
                }
                weed.forEach { d.drawPath(it, Color(0xFF4F9A5E).copy(alpha = 0.85f)) }
            })
        }
        Arena.MARS -> {
            // Steel panels with seams and rivets, vent slots, and a red stripe along the front.
            val panel = w * 2.6f
            val seams = List(((span - w) / panel).toInt().coerceAtLeast(0)) { k -> left + panel * (k + 1) }
            val rivets = (listOf(left + w * 0.18f, right - w * 0.18f) + seams.flatMap { listOf(it - w * 0.14f, it + w * 0.14f) })
            val vents = (listOf(left) + seams).map { x0 -> x0 + w * 0.45f }.filter { it + w * 0.5f < right - w * 0.3f }
            ({ d, look ->
                d.drawRect(Color(0xFFD9573E).copy(alpha = 0.85f), Offset(left, front + h * 0.16f), Size(span, h * 0.1f))
                d.drawRect(Color.White.copy(alpha = 0.25f), Offset(left, front + h * 0.16f), Size(span, h * 0.03f))
                seams.forEach {
                    d.drawLine(look.mark.copy(alpha = 0.5f), Offset(it, front), Offset(it, under), strokeWidth = w * 0.025f)
                    d.drawLine(look.edge.copy(alpha = 0.3f), Offset(it + w * 0.025f, front), Offset(it + w * 0.025f, under), strokeWidth = w * 0.012f)
                }
                for (x in rivets) for (y in listOf(front + h * 0.42f, front + h * 0.8f)) {
                    val c = Offset(x, y)
                    d.drawCircle(look.mark.copy(alpha = 0.55f), w * 0.035f, c + Offset(w * 0.006f, w * 0.008f))
                    d.drawCircle(look.topLight, w * 0.028f, c)
                    d.drawCircle(Color.White.copy(alpha = 0.7f), w * 0.01f, c - Offset(w * 0.009f, w * 0.009f))
                }
                vents.forEach { x ->
                    for (k in 0..2) {
                        d.drawLine(look.mark.copy(alpha = 0.6f), Offset(x + k * w * 0.2f, front + h * 0.5f), Offset(x + k * w * 0.2f, front + h * 0.72f), strokeWidth = w * 0.05f, cap = StrokeCap.Round)
                    }
                }
            })
        }
        Arena.DESERT -> {
            // A carved band of little triangles between two grooves, and strata in the stone.
            val band = Path().apply {
                val y1 = front + h * 0.3f
                val y2 = front + h * 0.68f
                val tooth = w * 0.32f
                var x = left + w * 0.2f
                moveTo(x, y2)
                while (x + tooth <= right - w * 0.2f) {
                    lineTo(x + tooth / 2, y1)
                    lineTo(x + tooth, y2)
                    x += tooth
                }
            }
            ({ d, look ->
                d.drawLine(look.mark.copy(alpha = 0.35f), Offset(left + w * 0.12f, front + h * 0.2f), Offset(right - w * 0.12f, front + h * 0.2f), strokeWidth = w * 0.03f)
                d.drawLine(look.mark.copy(alpha = 0.35f), Offset(left + w * 0.12f, front + h * 0.78f), Offset(right - w * 0.12f, front + h * 0.78f), strokeWidth = w * 0.03f)
                d.drawPath(band, look.mark.copy(alpha = 0.42f), style = Stroke(w * 0.035f))
                d.drawPath(band, look.edge.copy(alpha = 0.35f), style = Stroke(w * 0.015f))
            })
        }
    }
}

private val HAZARD = Color(0xFFF6BE2C)
