package io.colorsand.core

/**
 * The designed levels 1 to 30, one arena of [Arena.LEVELS] at a time, then endless generated ones.
 *
 * Each string is one tube, bottom to top; "" is an empty tube. Color codes: see [SandColor]. The designed
 * levels were dealt by [LevelGenerator] and picked by their shortest solution and by how much a greedy
 * player has to backtrack, so that each arena gets harder level by level up to its boss (its last level),
 * and opens a little easier than the last arena's boss. The tests prove every one solvable and pin their shortest solutions (see [Stars]).
 */
object Levels {
    val designed: List<Level> = listOf(
        // Playground: tubes of 4, two spare tubes (one on level 1), 2 to 6 colors.
        Level.parse(1, 4, "RRBB", "BBRR", ""), // the tutorial
        Level.parse(2, 4, "YRBY", "BYRR", "BRYB", "", ""), // 3 colors
        Level.parse(3, 4, "YYRG", "RBGB", "YGRB", "BGRY", "", ""), // 4 colors
        Level.parse(4, 4, "YRBP", "GBPR", "PRYP", "GYGR", "YBBG", "", ""), // 5 colors
        Level.parse(5, 4, "BBGO", "OYGP", "PGPO", "BYRO", "YGRR", "RYPB", "", ""), // 6 colors
        // Beach: half-built towers tempt you to finish them early; levels 8 and 10 are at low tide, with one
        // spare tube. 5 to 7 colors.
        Level.parse(6, 4, "BGPR", "YYRP", "RRPB", "GPYB", "GGYB", "", ""), // 5 colors
        Level.parse(7, 4, "OBYY", "OPRO", "GPRY", "RRGG", "OPBP", "BBYG", "", ""), // 6 colors
        Level.parse(8, 4, "BOOB", "GGGR", "BYBP", "PPPO", "YGOY", "RRRY", ""), // low tide
        Level.parse(9, 4, "KRGY", "GPKY", "OGKP", "BBBY", "OOPP", "RROK", "BGYR", "", ""), // 7 colors
        Level.parse(10, 4, "YYYG", "OGPY", "BGBR", "PPPO", "RORK", "BRGB", "KKKO", ""), // low tide
        // Sea Floor: more colors, towers and two spare tubes. 7 to 9 colors.
        Level.parse(11, 4, "BBRB", "RGYY", "PPOK", "YPYP", "OOGK", "GGKO", "RRKB", "", ""),
        Level.parse(12, 4, "PPPO", "GOYK", "KRYO", "RRBK", "RGBY", "KBOB", "GGYP", "", ""),
        Level.parse(13, 4, "CBGO", "PPOC", "YYOB", "PGKB", "YKCG", "RRYR", "PBGK", "OCRK", "", ""), // 8 colors
        Level.parse(14, 4, "YYYG", "RRCP", "ONGR", "KCGN", "OBBG", "RYNB", "OKCC", "PPBP", "OKKN", "", ""), // 9 colors
        Level.parse(15, 4, "KKNC", "YKCR", "CBYN", "OBRP", "GGPG", "YNYN", "OORP", "COBB", "PGKR", "", ""),
        // Desert: tubes of 5, two spare tubes. 6 to 8 colors.
        Level.parse(16, 5, "YPOYP", "GYOOR", "GPBGB", "GROYO", "RYRBB", "PPBRG", "", ""), // tubes of 5
        Level.parse(17, 5, "BKPOB", "BOPYY", "RRPGP", "KYBKG", "KOGGG", "RYRBO", "YKROP", "", ""), // 7 colors
        Level.parse(18, 5, "KGYRY", "OOPKG", "KPKRB", "PGBGB", "GBORO", "YKRYY", "PBOPR", "", ""),
        Level.parse(19, 5, "RKKCB", "YPPYP", "RYCGO", "GGCCR", "ORGCP", "YRYKB", "OOKBO", "PGBBK", "", ""), // 8 colors
        Level.parse(20, 5, "OCPCK", "CKRGR", "RPKCG", "OYYBB", "YGGBG", "RRPKB", "POPOY", "KYCBO", "", ""),
        // Building Site: tubes of 5 with towers three units high, two spare tubes. 7 to 9 colors.
        Level.parse(21, 5, "KRPYY", "OOOPR", "PRYGB", "BKYBY", "KGBKB", "ORPKR", "GGGOP", "", ""),
        Level.parse(22, 5, "OGPRB", "ORPRG", "BBBPK", "OGBGK", "YKRPR", "YYYKG", "KPOYO", "", ""),
        Level.parse(23, 5, // 8 colors
            "CGBPO", "GRYCY", "YYRYC", "OOORK", "PPPKK", "OCBGP", "BRBGR", "KBGCK", "", "",
        ),
        Level.parse(24, 5, // 9 colors
            "PNKGR", "YYYNO", "RKRNG", "RKPKY", "OGPGP", "GCRBB", "BBBKC", "OOOCY", "NCNCP", "", "",
        ),
        Level.parse(25, 5,
            "GRNRY", "GNKON", "PPPYO", "BBBYR", "BPRON", "CNOKK", "YRPKC", "GGGYC", "OCKBC", "", "",
        ),
        // Mars: tubes of 5, two spare tubes and the most colors, 9 to 11.
        Level.parse(26, 5,
            "KPROP", "BOOKC", "BYYCR", "RPYRN", "NRKBK", "COKCG", "GGNCG", "GBBPP", "NOYYN", "", "",
        ),
        Level.parse(27, 5, // 10 colors
            "CLLNG", "BCROO", "PPKKB", "NNLRO", "GPCLC", "BLRYP", "GOKNO", "BYRBC", "YGRGK", "YPKYN", "", "",
        ),
        Level.parse(28, 5,
            "KGYKK", "BNCRO", "YOCYB", "BBCGP", "PKRGL", "NCGLL", "ROCYN", "LROPY", "BNKLG", "RNOPP", "", "",
        ),
        Level.parse(29, 5, // 11 colors
            "BOCRP", "APLRO", "KNCNK", "KPGBO", "PLALB", "OYYCN", "AACRC", "GGOLL", "PYBRR", "NYBGG", "NYKAK", "", "",
        ),
        Level.parse(30, 5, // boss
            "LRKCY", "YRKNO", "YLPGA", "ABCCK", "NYGCN", "RBKAN", "KRPBL", "LAGYC", "OLOPG", "BBRPN", "AOGPO", "", "",
        ),
    )

    private val generated = HashMap<Int, Level>()

    /**
     * Level [number], 1-based. Numbers past the designed ones are generated deterministically and cached.
     * Not thread-safe: call it from one thread, such as the UI thread.
     */
    operator fun get(number: Int): Level {
        require(number >= 1) { "Level numbers start at 1, was $number" }
        return designed.getOrNull(number - 1) ?: generated.getOrPut(number) { LevelGenerator.generate(number) }
    }
}
