package io.colorsand.ui

import io.colorsand.core.Stars

/**
 * The levels whose keepsake game has been finished: each earns that level a keepsake star, a fourth star beside
 * its puzzle stars. Stored as text like "3,8,29". Unreadable entries are skipped.
 */
data class KeepsakeStars(val levels: Set<Int> = emptySet()) {
    operator fun contains(level: Int): Boolean = level in levels

    val total: Int get() = levels.size

    /** This record with [level]'s keepsake star. */
    fun record(level: Int): KeepsakeStars = if (level in levels || level < 1) this else KeepsakeStars(levels + level)

    fun encode(): String = levels.sorted().joinToString(",")

    companion object {
        /** The most stars a level can give: its puzzle stars and the keepsake star. */
        const val PER_LEVEL = Stars.MAX + 1

        fun decode(text: String?): KeepsakeStars = KeepsakeStars(
            text.orEmpty().split(',').mapNotNullTo(LinkedHashSet()) { it.trim().toIntOrNull()?.takeIf { l -> l >= 1 } },
        )
    }
}
