/**
 * Treasure dig: a patch of [arena]'s sand in a frame, three finds hidden under it (lost toys in the Playground's
 * sandbox, shells and a message in a bottle on the Beach, ice and fossils on Mars). Tap a square and a little
 * shovel digs it out with a puff of sand; empty holes glow hot, warm or cold by how near a find is. Finding all
 * three calls [onFinished]. There is no losing (see [TreasureDig]); [seed] picks where the finds lie.
 */
@Composable
fun TreasureDigGame(arena: Arena, seed: Int, feedback: Feedback, onFinished: () -> Unit, modifier: Modifier = Modifier) {
    val palette = LocalPalette.current
    val grade = remember(palette) { SceneGrade.of(palette) }
    val look = remember(arena, grade) { DigLook.of(arena, grade) }
    var round by remember(seed) { mutableStateOf(TreasureDig.start(seed)) }
    var status by remember(seed) { mutableStateOf(DigStatus.START) }
    var lastFind by remember(seed) { mutableStateOf<DigFind?>(null) }
    val digs = remember(seed) { List(round.cells) { Animatable(0f) } }
    val rises = remember(seed) { List(round.finds.size) { Animatable(0f) } }
    val bursts = remember(seed) { List(round.finds.size) { Animatable(0f) } }
    val clock = rememberInfiniteTransition(label = "dig").animateFloat(
        initialValue = 0f,
        targetValue = 1f,
        animationSpec = infiniteRepeatable(tween(GLOW_LOOP_MS, easing = LinearEasing)),
        label = "glow",
    )
    val scope = rememberCoroutineScope()
    fun dig(cell: Int) {
        val next = round.dig(cell)
        if (next === round) return
        round = next
        feedback.play(Sounds.land)
        feedback.tick()
        scope.launch { digs[cell].animateTo(1f, tween(DIG_MS, easing = LinearEasing)) }
        val find = next.findAt(cell)
        if (find != null) {
            lastFind = look.finds[find]
            status = if (next.isDone) DigStatus.ALL_FOUND else DigStatus.FOUND
            scope.launch {
                // Out of the hole once the shovel has broken the sand.
                delay((DIG_MS * HOLE_OPENS).toLong())
                feedback.play(Sounds.chime(next.found.size * 2))
                feedback.confirm()
                launch { bursts[find].animateTo(1f, tween(900, easing = FastOutSlowInEasing)) }
                rises[find].animateTo(1f, spring(dampingRatio = 0.45f, stiffness = Spring.StiffnessMediumLow))
            }
        } else {
            status = when (next.warmth(cell)) {
                Warmth.HOT -> DigStatus.HOT
                Warmth.WARM -> DigStatus.WARM
                else -> DigStatus.COLD
            }
        }
    }
    fun digNext() {
        (0 until round.cells).firstOrNull { it !in round.dug }?.let(::dig)
    }
    LaunchedEffect(round.isDone) {
        if (round.isDone) {
            delay(FINISH_DELAY_MS)
            onFinished()
        }
    }
    Column(modifier, horizontalAlignment = Alignment.CenterHorizontally) {
        Canvas(
            Modifier
                .weight(1f)
                .fillMaxWidth()
                // Screen readers and keyboards dig the next untouched square in reading order; the luck rule
                // (see TreasureDig.LUCK) still makes every round end.
                .semantics {
                    contentDescription = "A patch of sand to dig, ${round.found.size} of ${round.finds.size} found"
                    onClick(label = "Dig") { digNext(); true }
                }
                .onKeyEvent { event ->
                    val press = event.type == KeyEventType.KeyUp && (event.key == Key.Enter || event.key == Key.Spacebar)
                    if (press) digNext()
                    press
                }
                .focusable()
                .pointerInput(round.columns, round.rows) {
                    detectTapGestures { p ->
                        DigLayout(size.width.toFloat(), size.height.toFloat(), round.columns, round.rows).cellAt(p)?.let(::dig)
                    }
                },
        ) {
            val layout = DigLayout(size.width, size.height, round.columns, round.rows)
            drawDig(look, grade, layout, round, digs, rises, bursts, clock)
        }
        Spacer(Modifier.height(12.dp))
        FindsTray(look, grade, round, rises)
        Spacer(Modifier.height(10.dp))
        Text(
            status.text(lastFind?.name),
            color = palette.text,
            fontSize = 16.sp,
            fontWeight = FontWeight.Bold,
            textAlign = TextAlign.Center,
            maxLines = 1,
            modifier = Modifier
                .widthIn(max = 420.dp)
                .frosted(palette, RoundedCornerShape(50), elevation = 4.dp)
                .padding(horizontal = 18.dp, vertical = 8.dp)
                .semantics { liveRegion = LiveRegionMode.Polite },
        )
    }
}

/** What the line under the dig says after the last tap. */
private enum class DigStatus {
    START, HOT, WARM, COLD, FOUND, ALL_FOUND;

    fun text(find: String?): String = when (this) {
        START -> "Tap the sand to dig for treasure!"
        HOT -> "Hot! Treasure is right next to it!"
        WARM -> "Warm… it's somewhere close."
        COLD -> "Cold. Try somewhere else."
        FOUND -> "You found the $find!"
        ALL_FOUND -> "All found! What a treasure hunt!"
    }
}

/** The three finds in a row of round slots: a faint outline until each one is dug up, then the find itself. */
@Composable
private fun FindsTray(look: DigLook, grade: SceneGrade, round: TreasureDig, rises: List<Animatable<Float, *>>) {
    val palette = LocalPalette.current
    Row(horizontalArrangement = Arrangement.spacedBy(14.dp)) {
        look.finds.forEachIndexed { i, find ->
            val found = i in round.found
            Box(
                Modifier
                    .size(64.dp)
                    .frosted(palette, CircleShape, elevation = 5.dp)
                    .semantics { contentDescription = if (found) "Found the ${find.name}" else "Something still buried" },
                contentAlignment = Alignment.Center,
            ) {
                Canvas(
                    Modifier.fillMaxSize().padding(6.dp).graphicsLayer {
                        val pop = if (found) rises[i].value else 1f
                        scaleX = pop
                        scaleY = pop
                    },
                ) {
                    val unit = size.minDimension / 100f
                    scale(unit, unit, Offset.Zero) {
                        if (found) find.draw(this, grade) else silhouette(Color.Black.copy(alpha = 0.18f)) { find.draw(this, grade) }
                    }
                }
            }
        }
    }
}

/** The whole dig at this frame: the frame, every square or hole, the clues, the finds coming up and the shovels. */
private fun DrawScope.drawDig(
    look: DigLook,
    grade: SceneGrade,
    layout: DigLayout,
    round: TreasureDig,
    digs: List<Animatable<Float, *>>,
    rises: List<Animatable<Float, *>>,
    bursts: List<Animatable<Float, *>>,
    clock: State<Float>,
) {
    val t = clock.value
    val s = layout.cell
    drawDigFrame(look, layout)
    for (cell in 0 until round.cells) {
        val c = layout.center(cell)
        val p = if (cell in round.dug) digs[cell].value else 0f
        if (p < HOLE_OPENS) {
            drawSandSquare(look, c, s, cell + 1, press = p / HOLE_OPENS)
        } else {
            val open = openCurve((p - HOLE_OPENS) / (1f - HOLE_OPENS))
            drawHole(look, c, s, open)
            val find = round.findAt(cell)
            if (find == null) round.warmth(cell)?.let { drawClue(it, c, s, open, t, cell) }
        }
    }
    // The finds rise out of their holes over the squares around them.
    for (find in round.found) {
        val c = layout.center(round.finds[find])
        val rise = rises[find].value
        val burst = bursts[find].value
        if (burst > 0f && burst < 1f) drawGlow(c, s * (0.6f + 0.8f * burst), Color(0xFFFFF2B0).copy(alpha = 0.9f * (1f - burst)))
        if (rise > 0.01f) {
            drawGlow(c, s * 0.62f, Color(0xFFFFE27A).copy(alpha = 0.55f + 0.15f * sin(t * 2 * PI.toFloat() * 3)))
            val unit = s * (0.25f + 0.8f * rise) / 100f
            translate(c.x - 50f * unit, c.y - s * 0.16f * rise - 55f * unit) {
                scale(unit, unit, Offset.Zero) { look.finds[find].draw(this, grade) }
            }
        }
        if (burst > 0f && burst < 1f) sparkleBurst(c, s, burst)
    }
    for (cell in round.dug) {
        val p = digs[cell].value
        if (p < 1f) {
            val c = layout.center(cell)
            if (p >= HOLE_OPENS) sandPuff(look, c, s, (p - HOLE_OPENS) / (1f - HOLE_OPENS), cell)
            drawShovel(look, c, s, p)
        }
    }
    if (!round.isDone) glints(layout, round, t)
}
