package io.colorsand.ui.fx

import io.colorsand.ui.LIFT_END
import io.colorsand.ui.POUR_END
import io.colorsand.ui.POUR_MILLIS

/** One of the game's sound effects. Its [samples] are rendered the first time they are asked for, then kept. */
class Sound internal constructor(val name: String, render: () -> FloatArray) {
    val samples: FloatArray by lazy(render)

    override fun toString() = name
}

/**
 * The game's sound effects, synthesized in code: soft sines and filtered noise with gentle envelopes, kept short
 * and quiet so they sit under the cozy mood instead of beeping at the player.
 */
object Sounds {
    /** How long sand runs from the lifted tube during a pour (see [PourAnimation]), in milliseconds. */
    val streamMillis: Float = POUR_MILLIS * (POUR_END - LIFT_END)

    /** Picking a tube up: a rounded wooden "tok" that glides up a little. */
    val pick = Sound("pick") {
        val pcm = FloatArray(samples(120f))
        val body = Oscillator()
        val overtone = Oscillator()
        val noise = Noise(11)
        val knock = Biquad.bandPass(2200f, 1.2f)
        for (i in pcm.indices) {
            val f = glide(i, 520f, 780f, 22f)
            val env = ramp(i, samples(3f)) * decay(i, 32f)
            pcm[i] = env * (body.next(f) + 0.18f * overtone.next(f * 2.01f)) + 0.25f * decay(i, 4f) * knock.next(noise.next())
        }
        finish(pcm, 0.32f)
    }

    /** Sand running into a tube: a soft hiss, as long as the stream, with the patter of single grains in it. */
    val pour = Sound("pour") {
        val pcm = FloatArray(samples(streamMillis + 90f))
        val noise = Noise(23)
        val band = Biquad.bandPass(1700f, 0.5f)
        val soften = Biquad.lowPass(3800f)
        val grains = Biquad.bandPass(3000f, 4f)
        val wobble = Biquad.lowPass(18f)
        val rise = samples(70f)
        val fall = samples(140f)
        val sustain = pcm.size - fall
        for (i in pcm.indices) {
            val n = noise.next()
            // A slow random swell, so the stream sounds like it's flowing rather than a steady fan.
            val swell = 0.8f + 14f * wobble.next(noise.next())
            // Now and then a single grain ticks against the glass.
            val tick = if (noise.next() > 0.996f) noise.next() * 6f else 0f
            val env = ramp(i, rise) * (if (i < sustain) 1f else 1f - ramp(i - sustain, fall))
            pcm[i] = env * (swell * soften.next(band.next(n)) + 0.35f * grains.next(tick))
        }
        finish(pcm, 0.2f)
    }

    /** The last grains settling in the target: a muffled, low "fff-thup". */
    val land = Sound("land") {
        val pcm = FloatArray(samples(180f))
        val body = Oscillator()
        val noise = Noise(37)
        val muffle = Biquad.lowPass(900f)
        for (i in pcm.indices) {
            val env = ramp(i, samples(6f))
            pcm[i] = env * (0.6f * decay(i, 40f) * body.next(glide(i, 170f, 105f, 40f)) + decay(i, 28f) * muffle.next(noise.next()))
        }
        finish(pcm, 0.28f)
    }

    /** A pour that can't go: two soft, muted bumps, the second lower, like a polite "uh-uh". */
    val invalid = Sound("invalid") {
        val pcm = FloatArray(samples(230f))
        val noise = Noise(41)
        val muffle = Biquad.lowPass(500f)
        fun bump(start: Int, freq: Float, gain: Float) {
            val osc = Oscillator()
            for (i in 0 until pcm.size - start) {
                val env = ramp(i, samples(5f)) * decay(i, 34f)
                pcm[start + i] += gain * env * (osc.next(glide(i, freq * 1.25f, freq, 18f)) + 0.4f * muffle.next(noise.next()))
            }
        }
        bump(0, 200f, 1f)
        bump(samples(90f), 150f, 0.8f)
        finish(pcm, 0.36f)
    }

    // A major pentatonic run from G5 up, so any streak of chimes stays in tune with the level-solved arpeggio.
    private val chimeNotes = listOf(783.99f, 880.00f, 1046.50f, 1174.66f, 1318.51f, 1567.98f)

    /** The pitch, in Hz, of the chime for a streak of [streak] tubes finished in a row. It rises with the streak. */
    fun chimeFrequency(streak: Int): Float = chimeNotes[(streak - 1).coerceIn(0, chimeNotes.lastIndex)]

    private val bell = listOf(1f to 1f, 2.0f to 0.28f, 3.0f to 0.08f, 4.2f to 0.04f)

    private val chimes = chimeNotes.indices.map { step ->
        Sound("chime${step + 1}") {
            val pcm = FloatArray(samples(900f))
            val f = chimeNotes[step]
            addBell(pcm, 0, f, 1f, 260f, bell)
            // A fifth above, a moment later, for a little sparkle.
            addBell(pcm, samples(55f), f * 1.5f, 0.4f, 200f, bell)
            finish(pcm, 0.34f)
        }
    }

    /** A tube just filled with one color: a bright, soft chime, higher for each one finished in a row ([chimeFrequency]). */
    fun chime(streak: Int): Sound = chimes[(streak - 1).coerceIn(0, chimes.lastIndex)]

    /** The level is solved: a short, happy arpeggio up C major, the top note ringing a bit longer. */
    val solved = Sound("solved") {
        val pcm = FloatArray(samples(1300f))
        val notes = listOf(523.25f, 659.25f, 783.99f, 1046.50f)
        val mallet = listOf(1f to 1f, 4.0f to 0.1f, 2.0f to 0.12f)
        notes.forEachIndexed { k, f ->
            val last = k == notes.lastIndex
            addBell(pcm, samples(95f * k), f, if (last) 1f else 0.85f, if (last) 520f else 260f, mallet)
        }
        // The top note's octave, softly, so the end shimmers.
        addBell(pcm, samples(95f * 3 + 30f), 2093f, 0.18f, 380f, mallet)
        finish(pcm, 0.4f)
    }

    /** A button press: a tiny, soft tick. */
    val click = Sound("click") {
        val pcm = FloatArray(samples(45f))
        val osc = Oscillator()
        val noise = Noise(53)
        val band = Biquad.bandPass(3000f, 1.5f)
        for (i in pcm.indices) {
            pcm[i] = decay(i, 9f) * osc.next(glide(i, 1500f, 1050f, 6f)) + 0.4f * decay(i, 2.5f) * band.next(noise.next())
        }
        finish(pcm, 0.2f)
    }

    /** Every sound, for players that load them all up front. */
    val all: List<Sound> = listOf(pick, pour, land, invalid, solved, click) + chimes
}
